import json, os
OUT='/home/claude/dokuio.com/src/obsah/hu'
def page(slug, sab_file, sab_export, nazev, nazevA, popis, kat, ilu, slova, souvis, title, desc, perex, obsahPopis, obsah, kroky, online, hodi, nehodi, po, faq, zakony, souvPopis, vt, vd, vp='Ingyenes · PDF és Word · kb. 3 perc'):
    d = dict(nazev=nazev, nazevA=nazevA,
        katalog=dict(popis=popis, kategorie=kat, ilustrace=ilu, slova=slova),
        landing=dict(title=title, description=desc, perex=perex, obsahPopis=obsahPopis,
            obsah=[dict(nazev=a,popis=b) for a,b in obsah], kroky=[dict(nazev=a,popis=b) for a,b in kroky],
            online=online, hodiSe=hodi, nehodiSe=nehodi, po=[dict(nazev=a,popis=b) for a,b in po],
            faq=[dict(q=a,a=b) for a,b in faq], zakony=zakony, souvisejiciPopis=souvPopis),
        vytvorit=dict(title=vt, description=vd, podnadpis=vp))
    for k in ('title','description'):
        assert 20 <= len(d['landing'][k]) <= 170, (slug,k,len(d['landing'][k]))
    assert len(title.replace('{rok}','2026'))<=70, (slug,'title',len(title))
    assert 70<=len(desc)<=170, (slug,'desc',len(desc))
    assert len(vt)<=70 and 70<=len(vd)<=170, (slug,'vytvorit',len(vt),len(vd))
    ts = f"""import type {{ StrankaDokumentu }} from '../typy';
import {{ {sab_export} as sablona }} from '../../sablony/hu/{sab_file}';

const stranka: StrankaDokumentu = {{
  sablona,
  nazev: {json.dumps(nazev, ensure_ascii=False)},
  nazevA: {json.dumps(nazevA, ensure_ascii=False)},
  katalog: {json.dumps(d['katalog'], ensure_ascii=False, indent=2)},
  souvisejici: '{souvis}',
  landing: {json.dumps(d['landing'], ensure_ascii=False, indent=2)},
  vytvorit: {json.dumps(d['vytvorit'], ensure_ascii=False, indent=2)},
}};

export default stranka;
"""
    open(os.path.join(OUT, slug+'.ts'),'w').write(ts)

